hjjd:{n:"Hendrikus J. J. Degenhart",d:"b. 1836 · Kampen",b:1836,s:"b",p:["johannesd0", "mariador"],r:["nl"],t:"Born at Kampen on 3 April 1836, the son of a tailor. A cabinet maker, he married Maria Klara Vreenegoor at Zwolle in 1863.",src:[["Birth record, 1836", "https://www.openarchieven.nl/hco:644359DB-9BE7-41D2-A8AF-8A22233729B6"], ["Marriage, 1863", "https://www.openarchieven.nl/hco:D6569E41-EAC6-46B3-B9B1-C217F80EE620"]]},
