georg:{n:"Georg Bruckmann",d:"b. c. 1834 · Kassel",b:1834,s:"b",p:["jakobb", "marie"],r:["de", "nl"],t:"A seaman from Kassel in Hesse, the son of a cloth weaver. He married Hendrina Holst in Amsterdam on 18 December 1862, aged 28, bringing German ancestry into Carla's family.",src:[["Marriage, 1862", "https://www.openarchieven.nl/nha:C7DB11CC-8B28-403C-96C5-9CC631323CE9"]]},
