bernardus:{n:"Bernardus Hubertus van den Berg",d:"1826–1894 · Tilburg",b:1826,x:1894,s:"b",p:["bernardus0", "johannac"],r:["nl"],t:"Born at Tilburg on 13 January 1826, the son of Bernardus van den Berg and Johanna Cornelia de Vries. He married Maria Gertruda Hamers there on 25 April 1850, and died at Tilburg on 5 October 1894, aged 68.",src:[["Marriage, 1850", "https://www.openarchieven.nl/rat:0a04092c-3861-11e0-bcd1-8edf61960649"], ["Death record, 1894", "https://www.openarchieven.nl/rat:c78deeae-3861-11e0-bcd1-8edf61960649"]]},
