virgilr:{n:"Virgil Robert Frankish",d:"1832–1889",b:1832,x:1889,s:"f",p:["thomas1", "catherine"],r:["uk"],img:"img/hibaldstow.jpg",ch:"frankish",t:"Baptised on 16 September 1832 at Holy Trinity, Barrow upon Humber. His father died when he was barely a year old. He grew up to work in Hull, married Jane Batler there in 1854, and died in Sculcoates, Hull, late in 1889, aged 57, a few weeks after his son Thomas's wedding.",src:[["FreeREG parish registers", "https://www.freereg.org.uk/"], ["FreeBMD (England and Wales index)", "https://www.freebmd.org.uk/"]]},
