josephh:{n:"Joseph Hodgetts",d:"d. 1948",x:1948,s:"h",p:["josephh0", "sarahharris"],r:["au"],t:"Son of Joseph Hodgetts and Sarah Harris. He married Rosetta Maud Bastock on 17 October 1900. They farmed in the Rosedale district, then ran the strawberry gardens at Newtown, Bundaberg, a popular place for parties and outings, and raised thirteen children. He died on 27 December 1948 and is buried in the Bundaberg General Cemetery; his home was at Walkervale, Bundaberg.",src:[["Bundaberg News-Mail, 15 Feb 1958", "https://trove.nla.gov.au/newspaper/article/284352215"], ["Queensland marriage and death indexes", "https://www.familyhistory.bdm.qld.gov.au/"], ["Bundaberg cemetery records", "https://cemeterysearch.bundaberg.qld.gov.au/?q=Hodgetts"]]},
eliza:{n:'Eliza Ruth Warren',d:'1849–1927',b:1849,x:1927,s:'p',p:['josephw','maryfox'],r:['uk','au'],t:'Born in Plymouth and arrived in Melbourne aged four on the Parsee in 1854. She died at Yarra Junction in 1927.'},
elliott:{n:'Elliott Agar Webb',d:'1849–1928',b:1849,x:1928,s:'p',p:['drwebb','annagar'],r:['uk','au'],t:'Born at Vestry House, St Martin in the Fields, London, on 7 January 1849, a month after his father reached Adelaide. He followed him out in the 1860s. He married Martha Hicks at Laura, South Australia, in 1878, moved to Melbourne in 1887, and became an insurance agent in Richmond, where he died on 18 March 1928.'},
marthah:{n:'Martha Hicks',d:'c. 1852–1943',b:1852,x:1943,s:'p',p:['charlesh','anns'],r:['uk','au'],t:'Born in England and arrived at Port Adelaide aged two on the Telegraph in 1855. She married Elliott Webb at St John\'s, Laura, on 7 January 1878, and died at Bacchus Marsh in 1943.'},
