tjaardh:{n:"Tjaard Hindriks Broesder",d:"1808–1874",b:1808,x:1874,s:"b",p:["hindrik", "eisse"],r:["nl"],t:"Born on 14 December 1808 and baptised at Finsterwolde on Christmas Day. A farmhand when he married Anje Jans Lewe, a farm maid, at Nieuwolda in 1833. Died at Wagenborgen in 1874.",src:[["Baptism, 1808", "https://www.openarchieven.nl/gra:c69797d8-f242-a420-2c49-bda0126a7272"], ["Marriage, 1833", "https://www.openarchieven.nl/gra:12786296-077d-0984-0b70-9944f2ab3bd8"]]},
