jacobmm:{n:"Jacob Meines Meinsma",d:"c. 1783–1856",b:1783,x:1856,s:"h",p:["meine", "aukjenm"],r:["nl"],t:"A farmer at Wijnjeterp in Opsterland, the son of Meine and Aukjen. He married Ibeltje Hendriks; their daughter Aaltje was born around 1823. He died at Wijnjeterp on 13 October 1856, aged 73.",src:[["Death record, 1856", "https://www.openarchieven.nl/frl:e211ff9e-8fb2-6075-33da-64c534da20e9"]]},
