jilt:{n:"Jilt Jans Wijnstra",d:"c. 1830–1872 · Hemrik in Opsterland",b:1830,x:1872,s:"h",p:["janwijnstra", "albertjedv"],r:["nl"],t:"Born at Hemrik in Opsterland, the son of Jan Wijnstra and Albertje de Vries. On 1 May 1856, aged 26, he married Aukjen Feitzes de Vries of Lippenhuizen, and they had a large family there. He died at Lippenhuizen on 17 October 1872.",src:[["Marriage, 1856", "https://www.openarchieven.nl/frl:e5ed003c-34be-f6df-4c21-e6d5d4c808c9"], ["Death record, 1872", "https://www.openarchieven.nl/frl:32243268-7574-4367-8518-250ba4bbecbf"]]},
aukjenv:{n:"Aukjen Feitzes de Vries",d:"b. c. 1838 · Lippenhuizen",b:1838,s:"h",p:["feitzedv", "aukjenjansma"],r:["nl"],t:"Born at Lippenhuizen, the daughter of Feitze de Vries and Aukjen Jansma. She married Jilt Jans Wijnstra in 1856, aged 18, and was widowed in 1872.",src:[["Marriage, 1856", "https://www.openarchieven.nl/frl:e5ed003c-34be-f6df-4c21-e6d5d4c808c9"]]},
janlewe:{n:"Jan Jacobs Lewe",d:"1779–1826 · Wagenborgen",b:1779,x:1826,s:"b",p:["jakobkl", "gepke"],u:true,r:["nl"],t:"Born at Wagenborgen on 3 November 1779 and baptised there four days later, the son of Jakob Klaasens Leewe and Gepke Stoffers. When he first married, to Hilje Willems of Oude Pekela in 1806, the banns record that his father \"at first objected\". He later married Aaltje Okkes Eekstra. A labourer, he died at Wagenborgen on 17 December 1826, aged 47, leaving four children.",src:[["Baptism, 1779", "https://www.openarchieven.nl/gra:66d44236-4602-4d4d-52a9-3a88ab5edc50"], ["Banns, 1806", "https://www.openarchieven.nl/gra:5959de86-fa03-0031-e744-4f544adea0f8"], ["Death record, 1826", "https://www.openarchieven.nl/gra:80a20404-0bec-1afb-7aa3-daacc8c189d1"]]},
aaltjeok:{n:"Aaltje Okkes Eekstra",d:"1782–1864",b:1782,x:1864,s:"b",p:["okke", "anjed"],r:["nl"],t:"Baptised at Noordbroek on 24 March 1782, the year after her parents moved there from Eexta. She married Jan Jacobs Lewe and died at Wagenborgen on 28 February 1864, aged 82.",src:[["Baptism, 1782", "https://www.openarchieven.nl/gra:50fcb3cd-1074-2269-0b5f-3495b1f0824a"], ["Death record, 1864", "https://www.openarchieven.nl/gra:100c61e2-42f9-f5e1-1858-85cd746cfb12"]]},
okke:{n:"Okke (Ocko) Eijlderts Eekstra",sn:"Okke Eekstra",d:"m. 1764 Eexta",s:"b",p:[],r:["nl"],t:"Of Eexta, near Scheemda, which gave the family its later surname Eekstra. He married Anje Derks of Noordbroek at Eexta on 30 November 1764. Their children were baptised at Eexta from 1766 until 1781, when the family moved to Noordbroek.",src:[["Marriage, 1764", "https://www.openarchieven.nl/gra:89c64a0d-54f1-3b7e-841c-b2368822202b"]]},
anjed:{n:"Anje Derks",d:"of Noordbroek",s:"b",p:[],r:["nl"],t:"Of Noordbroek. She married Ocko Eijlderts of Eexta in 1764 and returned with the family to Noordbroek in 1781."},
harmh:{n:"Harm Hulzebosch",d:"1816–1903 · Oudeschans",b:1816,x:1903,s:"b",p:["janjh", "stijntje"],r:["nl"],t:"A tailor, born at Oudeschans on 15 January 1816. He married Helena Plat at Finsterwolde on 16 December 1842 and died at Noordbroek on 29 January 1903, aged 87.",src:[["Birth record, 1816", "https://www.openarchieven.nl/gra:03080cb3-4655-d889-e764-b76fca87b529"], ["Marriage, 1842", "https://www.openarchieven.nl/gra:66387e03-ac44-a964-4c83-c4e007ded74b"]]},
helena:{n:"Helena Plat",d:"1813–1880 · Finsterwolde",b:1813,x:1880,s:"b",p:["aaldrikp", "epkeh"],r:["nl"],t:"Born at Finsterwolde on 8 August 1813, a carter's daughter. Died at Noordbroek on 14 August 1880.",src:[["Death record, 1880", "https://www.openarchieven.nl/gra:bf020af7-e1b2-0cd6-4141-177a3dabd290"]]},
janjh:{n:"Jan Joosten Hulzebos",d:"c. 1776–1848 · Wymeer in East Frisia",b:1776,x:1848,s:"b",p:["joost", "gepke"],r:["de", "nl"],t:"A tailor, born at Wymeer in East Frisia, just over the German border. He married Stijntje Jacobs IJzer at Oudeschans on 1 June 1800, and died there on 8 February 1848, aged 72.",src:[["Marriage, 1800", "https://www.openarchieven.nl/gra:17cbb6b4-aaa6-e65e-48da-1b9fb6afbbb7"], ["Death record, 1848", "https://www.openarchieven.nl/gra:14bb3952-edf0-9dca-a524-f2ee12cd47e3"]]},
stijntje:{n:"Stijntje Jacobs IJzer",d:"c. 1780–1819",b:1780,x:1819,s:"b",p:["harmijzer", "antjejans"],r:["nl"],t:"Of Oudeschans, the daughter of the day labourer Harm Jacobs IJzer and Antje Jans. She married the tailor Jan Joosten Hulzebos from Wymeer in East Frisia, and was the mother of Harm (1816). She died at Oudeschans on 26 April 1819, aged 39.",src:[["Death record, 1819", "https://www.openarchieven.nl/gra:de197a07-af33-80b5-d0c4-c02a4d6ece07"]]},
joost:{n:"Joost Hulzebos",d:"day labourer, Wymeer",s:"b",p:[],r:["de"]},
gepke:{n:"Gepke Stoffers Toornman",sn:"Gepke Stoffers",d:"c. 1742–1809",b:1742,x:1809,s:"b",p:[],r:["nl"],t:"Of Wagenborgen, from the Toornman family, who stood on her side of the 1778 marriage contract. She was buried at Wagenborgen on 24 December 1809, aged 67, leaving four children.",src:[["Burial, 1809", "https://www.openarchieven.nl/gra:2ff5d2df-0a2d-ce63-1a74-e948bc8f86ad"]]},
