epkeh:{n:"Epke Derks Hekman",d:"c. 1786–1853 · Pekela",b:1786,x:1853,s:"b",p:[],r:["nl"],t:"Born at Pekela. She married the carter Aaldrik Wessels Plat and was the mother of Helena Plat (1813). She died at Finsterwolde on 10 February 1853, aged 67.",src:[["Death record, 1853", "https://www.openarchieven.nl/gra:57e41f55-d073-3fb3-1fb9-38e79f4bda0e"]]},
