howard:{n:"Howard Baldwin",d:"d. 1928 Queensland",x:1928,s:"y",p:["howard0", "elizabethbr"],r:["uk", "au"],t:"Married Anna Haill in the Bosmere district of Suffolk in 1864 and emigrated to Queensland, where he died in 1928, aged 83. He was buried in Toowong Cemetery, Brisbane, on 9 March 1928, and Anna was later buried with him.",src:[["Brisbane City Council memorial search", "https://brisbane.discovereverafter.com/profile/32006432"], ["Queensland BDM family history search", "https://familyhistory.bdm.qld.gov.au/"]]},
annahaill:{n:"Anna Haill",d:"d. 1939 Queensland",x:1939,s:"y",p:["williamhaill", "annapawsey"],r:["uk", "au"],t:"Married Howard Baldwin in Suffolk in 1864 and came with him to Queensland. She died on 30 September 1939 and is buried with Howard in Toowong Cemetery.",src:[["Brisbane City Council memorial search", "https://brisbane.discovereverafter.com/profile/32006432"], ["Queensland BDM family history search", "https://familyhistory.bdm.qld.gov.au/"]]},
