janrokus:{n:"Jan Rokus de Kreij",d:"1838–1920 · Schelluinen",b:1838,x:1920,s:"b",p:["ariekr", "gijsbertjeboer"],r:["nl"],t:"Born at Schelluinen on 12 July 1838, the son of the labourer Arie de Kreij and Gijsbertje de Boer; his father registered the birth that afternoon. A labourer himself, he married Lijntje Broere, and their children were born at Schelluinen from 1863, among them Gijsbertje, named after his mother. After Lijntje's death he married Wilhelmina Slagboom. He died at Schelluinen on 17 June 1920, aged 81, a widower for the second time.",src:[["Birth record, 1838", "https://www.openarchieven.nl/rag:0c4946fc-c527-4adc-6e28-24c06d12e90c"], ["Death record, 1920", "https://www.openarchieven.nl/rag:47a39f9b-8971-98ae-60b3-2adc51d4024c"]]},
lijntjeb:{n:"Lijntje Broere",d:"d. by 1876",s:"b",p:[],r:["nl"],t:"Wife of Jan Rokus de Kreij and mother of Gijsbertje. Her children were born at Schelluinen from 1863; she had died before 1876, when Jan Rokus's children were born to his second wife. Their son Arie died as a child at Peursum, near Schelluinen, in November 1863.",src:[["Birth of her daughter Lijntje, 1867", "https://www.openarchieven.nl/rag:8e348ba2-6e18-df42-b6f9-4b7799c883d0"],["Death of her son Arie, Peursum, 1863", "https://www.openarchieven.nl/rag:09ba3920-502b-f002-c6f4-016154fd3065"]]},
willembr:{n:"Willem de Bruijn",d:"1838–1875 · Hoornaar",b:1838,x:1875,s:"b",p:["leendertb0", "metjeh"],r:["nl"],t:"Born at Hoornaar on 22 February 1838, the son of Leendert de Bruijn and Metje Hagen. On 4 October 1867, aged 29, he married Jannigje van Veen at Meerkerk. Their children Leendert (1868), Katharina (1869), Kornelis (1870), Maarten (1872), Metje (1873) and Willempje (1875) were born at Hoornaar. He died there on 25 October 1875, aged 37, seventeen days after his youngest daughter was born.",src:[["Birth record, 1838", "https://www.openarchieven.nl/rag:00693f0e-7a19-bb9f-69f2-599493956883"], ["Marriage, 1867", "https://www.openarchieven.nl/rzh:d01513da-21dd-4b3d-bf4f-0fa27a135c98"], ["Death record, 1875", "https://www.openarchieven.nl/rag:d5b64e90-bb22-deca-f734-1b88a6871b36"]]},
jannigjev:{n:"Jannigje van Veen",d:"b. c. 1842 · Meerkerk",b:1842,s:"b",p:["cornelisvv", "catharinaw"],r:["nl"],t:"Born at Meerkerk, the daughter of Cornelis van Veen and Catharina Wink; her children Kornelis and Katharina carried her parents' names. She married Willem de Bruijn at Meerkerk in 1867, aged 25, and was left a widow at Hoornaar in 1875 with a house full of young children.",src:[["Marriage, 1867", "https://www.openarchieven.nl/rzh:d01513da-21dd-4b3d-bf4f-0fa27a135c98"]]},
leendertb0:{n:"Leendert de Bruijn",d:"d. 1863 Hoornaar",x:1863,s:"b",p:["jakobbr", "susannav"],r:["nl"],t:"Son of Jakob de Bruijn and Susanna Vaal. With Metje Hagen he raised a family at Hoornaar, where children were born to them from 1828, among them Willem in 1838. Widowed in 1844, he died at Hoornaar on 14 June 1863.",src:[["Death record, 1863", "https://www.openarchieven.nl/rag:783681a5-2f2f-eda0-1a35-ebea4af84841"]]},
metjeh:{n:"Metje Hagen",d:"d. 1844 Hoornaar",x:1844,s:"b",p:["franshagen", "marigjeb"],r:["nl"],t:"Daughter of Frans Hagen and Marigje Bronkhorst. She married Leendert de Bruijn and their children were born at Hoornaar between 1828 and 1843. She died there on 16 February 1844.",src:[["Death record, 1844", "https://www.openarchieven.nl/rag:cc28d411-3acf-f6a4-8341-aa445d4685fe"]]},
