gijsbertjeboer:{n:"Gijsbertje de Boer",d:"Schelluinen",s:"b",p:[],r:["nl"],t:"Wife of Arie de Kreij and mother of Jan Rokus de Kreij. Her granddaughter Gijsbertje de Kreij carried her name."},
henryharvey:{n:"Henry Augustus Harvey",s:"y",p:[],r:["au"],t:"Father of Ethel Augusta Harvey. With his wife Ellen Elizabeth Alcock he registered four children in country Queensland: Harold Augustus (1866, who died as a baby), Ethel Augusta (1868), Eleanor Frances Hoskins (1870) and Thurza Anne (1874).",src:[["Queensland BDM: births 1866/C/138, 1868/C/2865, 1870/C/3200, 1874/C/4438","https://familyhistory.bdm.qld.gov.au/"]]},
