romona:{"n": "Ramona Frankish", "sn": "Ramona (Romona) Frankish", "d": "", "s": "f", "p": ["walter", "mona"], "r": ["au"], "ch": "frankish", "t": "Walter and Mona’s only daughter, known in the family as Romona; the Perth papers spell her Ramona. In May 1941, when the family lived at Victoria Park, her uncle Private E. A. Fisk, Mona’s brother, wrote to her from the Middle East with the AIF about his leave in Jerusalem and Bethlehem, and the Daily News printed his letter. In 1949 and 1950 she was one of the mannequins in Perth fashion parades. She moved to Melbourne with her parents in 1952 or 1953.", "src": [["Letter from Private E. A. Fisk, Daily News (Perth), 27 May 1941", "https://trove.nla.gov.au/newspaper/article/83021295"], ["Fashion parade, West Australian, 24 Mar 1950", "https://trove.nla.gov.au/newspaper/article/47837258"], ["Death notices for Jesse Frankish, West Australian, 27 Dec 1948", "https://trove.nla.gov.au/newspaper/article/47633969"]]},
robertwf:{n:"Robert Wetherall Frankish",d:"1892–1973 · Hull",b:1892,x:1973,s:"f",p:["thomas2", "emily"],r:["uk", "au"],t:"Born in Hull in 1892. He stayed in Western Australia, married Nora McDermott in 1915, and died at Northam in 1973, aged 80."},
raaf:{n:'Robert Walter Wetherall Frankish',d:'1916–1943',b:1916,x:1943,s:'f',p:['robertwf',null],r:['au','uk'],t:'Lawrie\'s first cousin. A Flight Sergeant in the RAAF, killed on 18 September 1943 aged 27, and buried at Harrogate in Yorkshire.'},
margaret:{n:'Margaret Elaine Brazier',d:'b. 1932',b:1932,s:'y',p:['bruce','aileen'],r:['png','au'],img:'img/debutantes-1951.jpg',ch:'guinea',t:'Born in 1932, the elder daughter, while the family lived in the Territory of New Guinea. In November 1951 she made her debut at the Michaelmas Ball in Port Moresby, one of five debutantes photographed for Pacific Islands Monthly. In February 1956 she was visiting her grandmother at Hendra with her mother before they went back to Port Moresby.',src:[['Port Moresby Debutantes, PIM, 1 Nov 1951','https://nla.gov.au/nla.obj-331027255'],['Port Moresby Has City Comforts, Telegraph, 11 Feb 1956','https://trove.nla.gov.au/newspaper/article/293831648']]},
brucew:{n:'Bruce Warwick Brazier',d:'1941–2006',b:1941,x:2006,s:'y',p:['bruce','aileen'],r:['png','au'],t:'Born in 1941. He was a baby when his mother brought the three children south in the December 1941 evacuation; he landed at Brisbane from the Bulolo on 2 January 1951, aged nine, and by 1956 was boarding at Churchie. Died on 24 April 2006 aged 64, late of Indooroopilly.'},
charlesw:{n:'Charles Elliott Webb',d:'jeweller, Prahran',s:'p',p:['elliott','marthah'],r:['au'],t:'A jeweller and watchmaker in Greville Street, Prahran, who made the family brooch for his sister Mabel.'},
